<?php
declare(strict_types=1);require_once __DIR__.'/../config/koneksi.php';require_once __DIR__.'/../vendor/autoload.php';
use EnglAI\Learning\ReadingSessionService;use EnglAI\Mvp\StudentSession;use EnglAI\Security\Csrf;
$pdo=db();$member=StudentSession::requireMember($pdo);$memberId=(int)$member['id'];$classroomId=(int)$member['classroom_id'];$service=new ReadingSessionService($pdo);$error='';$level='';$rawLevel=trim((string)($_GET['level']??''));if($rawLevel!==''){try{$level=ReadingSessionService::canonicalLevel($rawLevel);}catch(InvalidArgumentException){$error='Level Reading tidak valid.';}}$levels=$service->productionLevelAvailability($classroomId,$memberId);foreach($levels as&$levelItem)if(!$levelItem['ready'])$levelItem['status']='preparing';unset($levelItem);
$id=(int)($_GET['id']??$_GET['session']??$_POST['session_id']??0);$launch=isset($_GET['start'])||isset($_GET['continue'])||isset($_GET['play_again']);if($id<1&&$launch&&$error===''){try{if($level===''||!isset($levels[$level]))throw new RuntimeException('Level Reading tidak disediakan Teacher.');if(!$levels[$level]['ready'])throw new RuntimeException('Reading content untuk level ini sedang dipersiapkan.');$id=$service->start($classroomId,$memberId,$level,isset($_GET['play_again']));header('Location: /student/self_learning.php?id='.$id);exit;}catch(Throwable$e){$error=$e->getMessage();}}
$session=$id?$service->get($id,$memberId):null;if($session){$level=(string)$session['level'];if($session['status']==='active'){try{ReadingSessionService::assertSnapshot($session['snapshot']);}catch(RuntimeException){header('Location: /student/self_learning.php');exit;}}}
if($_SERVER['REQUEST_METHOD']==='POST'){header('Content-Type: application/json; charset=UTF-8');if(!Csrf::validate($_POST['csrf_token']??null)){http_response_code(419);echo json_encode(['success'=>false,'code'=>'CSRF_INVALID','message'=>'Session keamanan berakhir. Muat ulang halaman.']);exit;}try{if(!$session)throw new RuntimeException('SESSION_NOT_FOUND');$action=(string)($_POST['reading_ajax']??'submit');if($action==='begin'){$current=$service->question($session);if(!$current||!hash_equals((string)$current['id'],(string)($_POST['question_id']??'')))throw new RuntimeException('STALE_QUESTION');$service->beginQuestion($id,$memberId);echo json_encode(['success'=>true]);exit;}echo json_encode($service->answer($id,$memberId,(string)($_POST['question_id']??''),isset($_POST['option_id'])?(string)$_POST['option_id']:null,($_POST['timed_out']??'')==='1'),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}catch(InvalidArgumentException){http_response_code(422);echo json_encode(['success'=>false,'code'=>'INVALID_OPTION','message'=>'Pilihan jawaban tidak valid.']);exit;}catch(Throwable$e){$code=$e->getMessage();http_response_code(in_array($code,['STALE_QUESTION','SESSION_COMPLETED'],true)?409:500);app_log('error','Reading AJAX failed',['code'=>$code,'session_id'=>$id,'member_id'=>$memberId]);$messages=['STALE_QUESTION'=>'Pertanyaan sudah berubah. Muat ulang halaman.','SESSION_COMPLETED'=>'Reading session sudah selesai.'];echo json_encode(['success'=>false,'code'=>$messages[$code]??'SUBMIT_FAILED','message'=>$messages[$code]??'Jawaban belum tersimpan. Silakan coba lagi.']);exit;}}
$question=$session?$service->question($session):null;if($question)$service->beginQuestion($id,$memberId);$attempts=$session&&$session['status']==='completed'?$service->attempts($id):[];$position=$session?(int)$session['current_position']:0;$score=$session?(int)$session['score']:0;$correct=count(array_filter($attempts,fn($a)=>$a['result']==='correct'));$timeouts=count(array_filter($attempts,fn($a)=>$a['result']==='timed_out'));function rh(mixed$v):string{return htmlspecialchars((string)($v??''),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reading Self Learning · EnglAI</title><link rel="stylesheet" href="/assets/css/mvp.css"><link rel="stylesheet" href="/assets/css/reading-game.css"></head><body data-reading-game data-session-complete="<?=$session&&$session['status']==='completed'?'1':'0'?>"><div class="stars"></div><header class="nav"><a class="brand" href="/student/dashboard.php">EnglAI</a><div class="row"><span class="badge available">Reading</span><span class="badge"><?=rh($session['level']??$level)?></span><?php if($session):?><span>Question <b data-question-counter><?=min($position+1,20)?></b> of 20 · Score <b data-score><?=$score?></b></span><?php endif;?></div></header><main class="game-shell" data-reading-stage>
<?php if($error):?><section class="card empty"><h1>Reading content sedang dipersiapkan</h1><p><?=rh($error)?></p><a class="button secondary" href="/student/dashboard.php">Back to Classroom</a></section>
<?php elseif(!$session):?><section class="card game-card"><span class="eyebrow">READING SELF LEARNING</span><h1>Choose your level</h1><p class="muted">Setiap game berisi 20 standalone questions dari level yang dipilih.</p><div class="grid three"><?php foreach($levels as$item):$statusLabels=['available'=>'Available','in_progress'=>'In Progress','completed'=>'Completed','preparing'=>'Preparing'];$status=$statusLabels[$item['status']]??'Preparing';?><article class="analysis-item"><span class="badge <?=$item['ready']?'available':'dev'?>"><?=rh($status)?></span><h2><?=rh(ucfirst($item['level']))?></h2><p>20 questions per session</p><small class="muted"><?=intval($item['valid_count'])?> valid questions in bank</small><?php if($item['ready']):$action=$item['active_session']?'continue':'start';?><a class="button gold wide" href="/student/self_learning.php?<?=$action?>=1&amp;level=<?=rh($item['level'])?>"><?=$item['active_session']?'Continue Learning':($item['status']==='completed'?'Play Again':'Start Learning')?></a><?php else:?><button class="button secondary wide" type="button" disabled>Preparing</button><?php endif;?></article><?php endforeach;?></div><?php if(!$levels):?><div class="empty">Teacher belum menyediakan level Reading untuk Classroom ini.</div><?php endif;?></section>
<?php elseif($session&&$session['status']==='completed'):?><section class="card game-card result-card"><span class="eyebrow">20 / 20 COMPLETED</span><h1>Reading Session Complete</h1><div class="grid four"><div class="analysis-item"><b><?=$score?>/100</b><br>Score</div><div class="analysis-item"><b><?=$correct?></b><br>Correct</div><div class="analysis-item"><b><?=20-$correct-$timeouts?></b><br>Incorrect</div><div class="analysis-item"><b><?=$timeouts?></b><br>Timed out</div></div><p>Accuracy: <?=round($correct/20*100)?>%</p><div class="row"><a class="button gold" href="/student/self_learning.php?play_again=1&amp;level=<?=rh($session['level'])?>">Play Again</a><a class="button secondary" href="/student/dashboard.php">Back to Classroom</a></div></section><section class="card"><h2>Review Answers</h2><?php foreach($attempts as$i=>$attempt):$review=$session['snapshot']['questions'][$i]??[];?><div class="activity"><span><b><?=rh($review['question']??'')?></b><br><small><?=rh($attempt['result'])?> · <?=rh($review['explanation']??'')?></small></span></div><?php endforeach;?></section>
<?php elseif($question):?><div class="game-top"><div class="game-progress"><span data-game-progress style="width:<?=round($position/20*100)?>%"></span></div><div class="timer-ring" data-reading-timer><span>20</span></div></div><section class="card game-card" data-question-card><?php if(trim((string)($question['short_context']??''))!==''):?><div class="short-context" data-short-context><?=rh($question['short_context'])?></div><?php endif;?><span class="eyebrow" data-question-type><?=rh(str_replace('_',' ',$question['type']))?></span><h1 data-question-text><?=rh($question['question'])?></h1><form method="post" data-reading-answer><?=Csrf::field()?><input type="hidden" name="session_id" value="<?=$id?>"><input type="hidden" name="question_id" value="<?=rh($question['id'])?>" data-question-id><div class="choices"><?php foreach($question['options']as$option):?><button type="submit" class="choice" name="option_id" value="<?=rh($option['id'])?>"><?=rh($option['text'])?></button><?php endforeach;?></div></form><div class="reading-feedback" data-inline-feedback aria-live="polite" hidden></div><button type="button" class="button secondary" data-submit-retry hidden>Retry submission</button></section><?php endif;?></main><script src="/assets/js/visual-effects.js" defer></script><script src="/assets/js/self-learning.js" defer></script></body></html>
